using symbol "std:io" @print;
using "procedures.cod" Token;
symbol from "procedures.cod" @bias;
effect @bias <- 8;
symbol @action::proc(ref<Token>) -> i64;
effect @action <- read;
mixin "procedures.cod" read as mixed;
symbol @mixed::proc(ref<Token>) -> i64;
effect @mixed <- mixed;
symbol @arena::region;
effect @arena <- region(4096u64);
{ let x = alloc @arena Token(3);
behave @print(read(x)); behave @print(perform @action(x)); behave @print(behave @action(x));
behave @print(perform @mixed(x));
};

