array Buffer[u32]::i64;
function create(arena::region)::ref<Buffer> { alloc arena Buffer(3u32, 7) }
function sum(buffer::ref<Buffer>)::i64 { fold (i in 0u32 .. u32(len(buffer)), total = 0) { total + buffer[i] } }

